mapper.select:
SELECT COUNT(*)
FROM (
    SELECT user_id, create_time
    FROM answer_record
    WHERE result = 1
    UNION ALL
    SELECT user_id, answered_time AS create_time
    FROM interview_turn
    WHERE status = 2 AND result = 1
) correct_record
WHERE user_id = #{userId}
  AND create_time >= #{start}
  AND create_time < #{end}

SELECT user_id, COUNT(*) AS count FROM ( SELECT user_id, create_time FROM answer_record WHERE result = 1 UNION ALL SELECT user_id, answered_time AS create_time FROM interview_turn WHERE status = 2 AND result = 1 ) correct_record
create_time >= #{start}
AND create_time < #{end}
GROUP BY user_id ORDER BY count DESC, user_id ASC LIMIT #{limit}
